import{_ as e,o as t,c as o,a2 as s}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"内部机制：崩溃转储","description":"","frontmatter":{},"headers":[],"relativePath":"zh/internals/crash-dump.md","filePath":"zh/internals/crash-dump.md"}'),r={name:"zh/internals/crash-dump.md"};function c(i,a,d,l,n,h){return t(),o("div",null,[...a[0]||(a[0]=[s(`<h1 id="内部机制-崩溃转储" tabindex="-1">内部机制：崩溃转储 <a class="header-anchor" href="#内部机制-崩溃转储" aria-label="Permalink to &quot;内部机制：崩溃转储&quot;">​</a></h1><p><code>kernel/core/core_crash.c</code> + <code>arch_exceptions.c</code> 中的异常处理路径。</p><h2 id="恐慌序列" tabindex="-1">恐慌序列 <a class="header-anchor" href="#恐慌序列" aria-label="Permalink to &quot;恐慌序列&quot;">​</a></h2><ol><li>异常存根构建帧（向量、RIP、寄存器，以及相关的 CR2/CR3）。</li><li>转储器将其打印到串口 - 即报告所需的确切行。</li><li>崩溃日志记录写入 /etc - 可在重启后保留。</li><li>机器停止运行（或者如果已启用硬件看门狗，则看门狗会重置它 - 参见 <a href="./watchdog.html">watchdog.md</a>）。</li></ol><h2 id="重启后" tabindex="-1">重启后 <a class="header-anchor" href="#重启后" aria-label="Permalink to &quot;重启后&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; crashlog      (the record list)</span></span>
<span class="line"><span>oc&gt; dumpinfo      (the decoded dump: vector, fault address, registers)</span></span></code></pre></div><h2 id="ist-为何在此处重要" tabindex="-1">IST 为何在此处重要 <a class="header-anchor" href="#ist-为何在此处重要" aria-label="Permalink to &quot;IST 为何在此处重要&quot;">​</a></h2><p>#DF（双重错误）和 #MC 在 IST1 上运行 - 使用它们自己的栈 - 因此在故障处理程序期间发生的故障仍能到达转储器。异常退出路径绝不会在 IST2 上进行上下文切换（BUG-0139）：在 IST 上进行上下文切换会破坏下一个嵌套故障的异常帧。</p><h2 id="测试方法" tabindex="-1">测试方法 <a class="header-anchor" href="#测试方法" aria-label="Permalink to &quot;测试方法&quot;">​</a></h2><p><code>crashtest</code> = 故意引发恐慌，然后 <code>dumpinfo</code> 证明往返过程。回归测试套件在每次运行时检查 <code>crashlog</code>。</p>`,10)])])}const m=e(r,[["render",c]]);export{u as __pageData,m as default};
